package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerTelephoneException;

/**
 * Rejects a create-owner request whose normalized telephone is already used by any existing
 * owner. Runs after {@link ValidateNewOwner} has normalized the request's telephone to its 10
 * digits, and before {@link BuildOwner}, so a duplicate is a 409 rather than a persisted record.
 * Each stored owner's telephone is normalized the same way (non-digits stripped) before comparing.
 */
public class CheckOwnerTelephoneUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerTelephoneException {
        String telephone = normalize(request.getTelephone());
        for (Owner owner : ownerRepository.findAll()) {
            if (telephone.equals(normalize(owner.getTelephone()))) {
                throw new DuplicateOwnerTelephoneException(request.getTelephone());
            }
        }
    }

    private static String normalize(String telephone) {
        return telephone == null ? "" : telephone.replaceAll("\\D", "");
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}. Rejects a request that is missing or blank in any
 * required field (firstName, lastName, address, city, telephone) with a 400 whose body lists
 * the offending field names. Then normalizes the telephone by stripping every non-digit
 * character and requires exactly 10 digits, storing the 10-digit value back on the request so
 * later steps persist and return it; a telephone that is not exactly 10 digits after stripping
 * is rejected with a 400. Runs before {@link BuildOwner} maps the body to an {@link
 * org.springframework.samples.petclinic.model.Owner}.
 */
public class ValidateNewOwner {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        String normalized = request.getTelephone().replaceAll("\\D", "");
        if (normalized.length() != 10) {
            throw new InvalidTelephoneException(request.getTelephone());
        }
        request.setTelephone(normalized);
        request.setEmail(OwnerEmail.normalize(request.getEmail()));
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request's telephone is not exactly 10 digits after every
 * non-digit character has been stripped. Handled globally by {@link
 * InvalidTelephoneExceptionHandler}, which responds 400.
 */
public class InvalidTelephoneException extends Exception {

    public InvalidTelephoneException(String telephone) {
        super("Telephone must be exactly 10 digits after removing non-digit characters: " + telephone);
    }
}
package org.springframework.samples.petclinic.rest.escalation;

import java.util.List;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class InvalidTelephoneExceptionHandler {

    /** Body shape: {@code {"errors": ["telephone"]}}. */
    public record InvalidField(List<String> errors) {
    }

    public void handle(@Parameter InvalidTelephoneException ex,
            ObjectResponse<ResponseEntity<InvalidField>> response) {
        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new InvalidField(List.of("telephone"))));
    }
}
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown by the create-owner pipeline when the request's normalized telephone is already used by
 * another owner. Handled globally by {@link DuplicateOwnerTelephoneExceptionHandler}, which
 * responds 409.
 */
public class DuplicateOwnerTelephoneException extends Exception {

    public DuplicateOwnerTelephoneException(String telephone) {
        super("An owner with telephone " + telephone + " already exists");
    }
}

